const extraTerms={source:["HTTP","SSH","Landing zone","ETL"],cdc:["Upsert"],engine:["Driver Spark"],transform:["Managed Service for Apache Flink","SDK"],broker:["Managed Service for Apache Kafka"],database:["JSON","KQL"],query:["KQL"],network:["Azure VPN Gateway"],capacity:["Driver Spark"]};
function termTitle(term){
 return phrase(term,glossary[term].title||term);
}
function questionResources(id,title){
 const entries=[...new Set([...questionHelp[id][4].split("|"),...(extraTerms[id]??[])])];
 const wrapLink=(content,attributes)=>'<a href="#questionHelpDialog" '+attributes+'>'+esc(content)+'</a>';
 const links=entries.map(term=>wrapLink(termTitle(term),'data-term="'+esc(term)+'"')).join("");
 by("questionResources").innerHTML='<h3>'+esc(phrase("Aiuto per questa domanda","Help for this question"))+'</h3><p>'+wrapLink(phrase("Cosa chiede e perché conta","What it asks and why it matters"),'data-guide="'+id+'"')+'</p><h4>'+esc(phrase("Tecnologie, architetture e acronimi","Technologies, architectures and acronyms"))+'</h4><div class="glossary-links">'+links+'</div>';
 by("questionResources").dataset.title=title;
}
let referenceHelpOpener;
function openReferenceHelp(opener,title,content){
 referenceHelpOpener=opener;
 by("helpTitle").textContent=title;
 by("helpContent").innerHTML=content;
 by("closeHelp").textContent=phrase("Chiudi","Close");
 by("questionHelpDialog").showModal();
}
function setupQuestionHelp(){
 by("questionResources").addEventListener("click",event=>{
   const link=event.target.closest("a[data-guide],a[data-term]");
   if(!link)return;
   event.preventDefault();
   const term=link.dataset.term;
   if(term){
     openReferenceHelp(link,termTitle(term),"<p>"+esc(glossary[term][language])+"</p>");
   }else{
     const [askIt,whyIt,askEn,whyEn]=questionHelp[link.dataset.guide];
     openReferenceHelp(link,by("questionResources").dataset.title,
       "<h3>"+esc(phrase("Cosa chiarire","What to clarify"))+"</h3><p>"+esc(phrase(askIt,askEn))+"</p><h3>"+esc(phrase("Perché conta per l’architettura","Why it matters for architecture"))+"</h3><p>"+esc(phrase(whyIt,whyEn))+"</p>");
   }
 });
 by("questionHelpDialog").addEventListener("close",()=>{
   referenceHelpOpener?.focus();
   referenceHelpOpener=undefined;
 });
}
